SELECT pp.id AS position_id, pp.signal_id, pp.symbol, pp.opened_at AS opened_stored, DATE_ADD(pp.opened_at, INTERVAL 3 HOUR) AS opened_ksa_assuming_utc, pp.closed_at AS closed_stored, DATE_ADD(pp.closed_at, INTERVAL 3 HOUR) AS closed_ksa_assuming_utc, @@session.time_zone AS session_time_zone, @@global.time_zone AS global_time_zone, NOW() AS mysql_now_session, UTC_TIMESTAMP() AS mysql_utc_now FROM paper_position pp WHERE pp.signal_id = 89469